function validate([edges, patience]) {
  const n = patience.length;
  if (n < 2 || n > 100000) return 'patience needs 2 to 10^5 entries.';
  if (patience[0] !== 0) return 'patience[0] must be 0.';
  for (let i = 1; i < n; i++) {
    if (!Number.isInteger(patience[i]) || patience[i] < 1 || patience[i] > 100000) return 'Each data server has patience from 1 to 10^5.';
  }
  if (!Array.isArray(edges) || edges.length < 1 || edges.length > Math.min(100000, n * (n - 1) / 2)) return 'edges needs between 1 and min(10^5, n(n-1)/2) links.';
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = a => { while (parent[a] !== a) { parent[a] = parent[parent[a]]; a = parent[a]; } return a; };
  const seen = new Set();
  let parts = n;
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 0 || v < 0 || u >= n || v >= n) return 'Edge ends must be servers 0 to n - 1.';
    if (u === v) return 'An edge cannot join a server to itself.';
    const key = Math.min(u, v) * n + Math.max(u, v);
    if (seen.has(key)) return 'Edges must not repeat.';
    seen.add(key);
    const a = find(u), b = find(v);
    if (a !== b) { parent[a] = b; parts--; }
  }
  if (parts !== 1) return 'All servers must be connected.';
  return null;
}

