function networkBecomesIdle(edges, patience) {
  const n = patience.length;
  const dist = new Array(n).fill(Infinity);
  dist[0] = 0;
  // Bellman-Ford style relaxation: n rounds over every link.
  for (let round = 0; round < n; round++) {
    for (const [u, v] of edges) {
      if (dist[u] + 1 < dist[v]) dist[v] = dist[u] + 1;
      if (dist[v] + 1 < dist[u]) dist[u] = dist[v] + 1;
    }
  }
  let idle = 0;
  for (let i = 1; i < n; i++) {
    const trip = 2 * dist[i];
    let lastSent = 0;
    // Simulate the server second by second until its first answer arrives.
    for (let t = 1; t < trip; t++) {
      if (t - lastSent === patience[i]) lastSent = t;
    }
    // The answer to the last copy arrives at lastSent + trip; the network is idle one second later.
    idle = Math.max(idle, lastSent + trip + 1);
  }
  return idle;
}

