function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1000, 2000) : int(2, 7);
  const labels = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = int(0, i);
    [labels[i], labels[j]] = [labels[j], labels[i]];
  }
  const shape = int(0, 2);
  const edges = [];
  const seen = new Set();
  const add = (a, b) => {
    const key = Math.min(a, b) * n + Math.max(a, b);
    if (a === b || seen.has(key)) return;
    seen.add(key);
    edges.push(rand() < 0.5 ? [a, b] : [b, a]);
  };
  // A spanning tree keeps the network connected: a path, a random tree, or a bushy tree.
  for (let i = 1; i < n; i++) {
    const parent = shape === 0 ? i - 1 : shape === 1 ? int(0, i - 1) : int(0, Math.min(i - 1, 3));
    add(labels[i], labels[parent]);
  }
  const cap = Math.min(size === 'large' ? 2000 : 12, n * (n - 1) / 2);
  const want = int(n - 1, cap);
  for (let tries = 0; edges.length < want && tries < 20 * want; tries++) add(int(0, n - 1), int(0, n - 1));
  for (let i = edges.length - 1; i > 0; i--) {
    const j = int(0, i);
    [edges[i], edges[j]] = [edges[j], edges[i]];
  }
  const top = size === 'large' ? [10, 4000, 100000][int(0, 2)] : (rand() < 0.8 ? 6 : 100000);
  const patience = Array.from({ length: n }, (_, i) => (i === 0 ? 0 : int(1, top)));
  return [edges, patience];
}
